  // --- Refresh slot visuals from data ---
  function refreshSlots(detail) {
    const pinnedSlots = Array.isArray(detail?.pinnedSlots) ? detail.pinnedSlots : [];
    const mana = Number(detail?.mana || 0);
    const stamina = Number(detail?.stamina || 0);
    _cachedMana = mana;

    let anyAssigned = false;
    for (let i = 0; i < SLOT_COUNT; i++) {
      const entry = (i < pinnedSlots.length) ? pinnedSlots[i] : null;
      const s = slots[i];
      s.entry = entry || null;
      s.spellId = entry?.kind === 'spell' ? (entry?.id || null) : null;

      if (entry?.kind === 'item-use' && entry?.id) {
        anyAssigned = true;
        const iconRef = resolveIconReference(entry);
        applyAtlasIcon(s.glyphSpan, iconRef, entry.symbol || '!', 28);
        s.glyphSpan.style.opacity = '1';
        const cdRemaining = Number(entry.cdRemaining || 0);
        const cdMax = Number(entry.cdMax || 0);
        const onCooldown = cdRemaining > 0 && cdMax > 0;

        s.btn.style.opacity = onCooldown ? '0.5' : '1';
        s.btn.style.borderColor = '#6e5f2b';
        s.btn.title = `${entry.name || entry.id}${onCooldown ? ` [${cdRemaining}]` : ''}`;
        s.manaBadge.style.display = 'none';

        if (onCooldown) {
          const pct = (1 - cdRemaining / cdMax) * 100;
          s.cdOverlay.style.background = `conic-gradient(from 0deg, transparent ${pct}%, rgba(0,0,0,0.55) ${pct}%)`;
          s.cdOverlay.style.display = 'block';
          s.cdLabel.textContent = String(cdRemaining);
          s.cdLabel.style.display = 'block';
        } else {
          s.cdOverlay.style.display = 'none';
          s.cdLabel.style.display = 'none';
        }
      } else if (entry && entry.id) {
        anyAssigned = true;
        const iconRef = entry.kind === 'item-use'
          ? resolveIconReference(entry)
          : resolveIconReference({ ...entry, iconAtlas: 'spells' });
        applyAtlasIcon(s.glyphSpan, iconRef, entry.symbol || '\u2726', 28);
        s.glyphSpan.style.opacity = '1';
        const cost = Number(entry.cost || 0);
        const resource = String(entry.costKind || 'mana');
        const canAfford = (resource === 'stamina' ? stamina : mana) >= cost;
        const cdRemaining = Number(entry.cdRemaining || 0);
        const cdMax = Number(entry.cdMax || 0);
        const onCooldown = cdRemaining > 0 && cdMax > 0;

        s.btn.style.opacity = (canAfford && !onCooldown) ? '1' : '0.5';
        s.btn.style.borderColor = '#2d3b52';
        const label = resource === 'stamina' ? 'stamina' : resource === 'life' ? 'life' : 'mana';
        s.btn.title = `${entry.name || entry.id} (${cost} ${label})${onCooldown ? ` [${cdRemaining}]` : ''}`;

        s.manaBadge.textContent = cost > 0 ? String(cost) : '';
        s.manaBadge.style.display = cost > 0 ? 'block' : 'none';

        if (onCooldown) {
          const pct = (1 - cdRemaining / cdMax) * 100;
          s.cdOverlay.style.background = `conic-gradient(from 0deg, transparent ${pct}%, rgba(0,0,0,0.55) ${pct}%)`;
          s.cdOverlay.style.display = 'block';
          s.cdLabel.textContent = String(cdRemaining);
          s.cdLabel.style.display = 'block';
        } else {
          s.cdOverlay.style.display = 'none';
          s.cdLabel.style.display = 'none';
        }
  }

  // --- Fan item rendering ---
  function renderFanItems(spells, activeId) {
    fan.innerHTML = '';
    _fanItems = [];
    const count = spells.length;
    if (count === 0) return;

    // Quarter-circle arc from 90° (up) to 180° (left), facing into the game field
    const RADIUS = 90;
    const ARC_START = 90;
    const ARC_END = 180;
    const ARC_SPAN = ARC_END - ARC_START;
    const HALF_ITEM = 22; // half of 44px item

    for (let i = 0; i < count; i++) {
      const spell = spells[i];
      const angle = count === 1
        ? (ARC_START + ARC_END) / 2
        : ARC_START + (ARC_SPAN * i / (count - 1));
      const rad = angle * Math.PI / 180;
      // Position from bottom-right of trigger: right increases leftward, bottom increases upward
      const r = 28 - Math.cos(rad) * RADIUS - HALF_ITEM;
      const b = 28 + Math.sin(rad) * RADIUS - HALF_ITEM;

      const isActive = spell.id === activeId;
      const item = document.createElement('div');
      item.dataset.spellId = spell.id;
      Object.assign(item.style, {
        position: 'absolute',
        width: '44px', height: '44px', borderRadius: '50%',
        border: isActive ? '2px solid #6b8fbf' : '1px solid #2d3b52',
        background: isActive ? '#152035' : '#101626',
        color: '#cfe8ff', fontSize: '20px',
        display: 'grid', placeItems: 'center',
        right: r + 'px',
        bottom: b + 'px',
        cursor: 'pointer',
        pointerEvents: 'auto',
        boxShadow: '0 2px 6px rgba(0,0,0,0.4)',
        transition: 'opacity 0.14s ease, transform 0.18s cubic-bezier(0.2, 0.9, 0.2, 1), border-color 0.16s ease, background-color 0.16s ease, box-shadow 0.16s ease',
        opacity: '0',
        transform: 'scale(0.86)',
      });
      item.dataset.baseBorder = isActive ? '2px solid #6b8fbf' : '1px solid #2d3b52';
      item.dataset.baseBg = isActive ? '#152035' : '#101626';

      const sym = document.createElement('span');
      const iconRef = resolveIconReference({ ...spell, iconAtlas: 'spells' });
      applyAtlasIcon(sym, iconRef, spell.symbol || '\u2726', 30);
      sym.style.lineHeight = '1';
      sym.style.pointerEvents = 'none';
      item.appendChild(sym);

      // Spell name label
      const label = document.createElement('span');
      const name = spell.name || spell.id;
      label.textContent = name.length > 6 ? name.slice(0, 5) + '\u2026' : name;
      Object.assign(label.style, {
        position: 'absolute', bottom: '-15px', left: '-8px', right: '-8px',
        textAlign: 'center', fontSize: '9px', color: '#cfe8ff',
        background: '#1a2744', borderRadius: '3px', padding: '2px 0',
        pointerEvents: 'none', whiteSpace: 'nowrap',
      });
      item.appendChild(label);
    sectorsEl.textContent = `Profitable sectors: ${sectors.join(', ')}`;
    Object.assign(sectorsEl.style, {
      marginTop: '8px',
      fontSize: '11px',
      color: '#c0def8',
      opacity: '0.9',
    });
    el.appendChild(sectorsEl);
  }
}


/** @param {HTMLDivElement & {_inner?:HTMLDivElement}} panel @param {Array<{id:string,name:string,symbol?:string,cost?:number,description?:string,targetEffects?:string[]}>} spells @param {string|null} activeId */
export function renderSpellPicker(panel, spells, activeId, bindSlot) {
  const el = /** @type {HTMLDivElement} */ (/** @type {any} */(panel)._inner);
  el.innerHTML = '';
  const title = document.createElement('div');
  title.textContent = typeof bindSlot === 'number'
    ? `Bind Spell to Slot ${bindSlot + 1}`
    : 'Select Active Spell';
  title.style.fontWeight = 'bold';
  title.style.marginBottom = '8px';
  el.appendChild(title);

  if (!spells.length) {
    const empty = document.createElement('div');
    empty.textContent = '(no learned spells)';
    el.appendChild(empty);
    return;
  }

  const list = document.createElement('div');
  list.style.display = 'flex'; list.style.flexDirection = 'column'; list.style.gap = '6px';
  el.appendChild(list);

  for (const sp of spells) {
    const row = document.createElement('div');
    Object.assign(row.style, {
      display: 'flex', alignItems: 'flex-start', gap: '8px',
      flexDirection: 'column',
      padding: '6px 8px', border: sp.id === activeId ? `1px solid ${UX_THEME.accentBorder}` : UI.BORDER, borderRadius: UI.RADIUS,
      background: sp.id === activeId ? UI.SEL_BG : UI.DEFAULT_BG, cursor: 'pointer'
    });
    const head = document.createElement('div');
    Object.assign(head.style, {
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      width: '100%',
    });
    if (sp.symbol) {
      const sym = document.createElement('span');
      sym.textContent = sp.symbol;
      sym.style.fontSize = '18px';
      head.appendChild(sym);
    }
    const name = document.createElement('span');
    name.textContent = sp.name ? `[${sp.name}]` : `[${sp.id}]`;
    const cost = document.createElement('span');
    cost.style.marginLeft = 'auto'; cost.style.opacity = '0.8'; cost.textContent = sp.cost ? `Mana ${sp.cost}` : '';
    head.appendChild(name);
    head.appendChild(cost);
    row.appendChild(head);

