  assert(ITEM_ICON_ATLAS.entries.has("scroll_identify"));
  assert(ITEM_ICON_ATLAS.entries.has("potion_health"));
  assert(ITEM_ICON_ATLAS.entries.has("healing_potion"));
  assert(ITEM_ICON_ATLAS.entries.has("wand_arcane"));
