  assert(CORPSE_ICON_ATLAS.sheetUrl.endsWith("/assets/icons/corpses/sheet.webp"));
  assertEquals(ICON_ATLASES.corpses, CORPSE_ICON_ATLAS);
});

Deno.test("class atlas consumes the manifest-selected sheet", () => {
